#!/usr/bin/env bash
set -Eeuo pipefail

# Runs on the VM. Required environment: MYSQL_HOST, SAKAI_DB_PASSWORD,
# SAKAI_PUBLIC_FQDN. It writes the runtime-only local.properties file.
: "${MYSQL_HOST:?MYSQL_HOST is required}"
: "${SAKAI_DB_PASSWORD:?SAKAI_DB_PASSWORD is required}"
: "${SAKAI_PUBLIC_FQDN:?SAKAI_PUBLIC_FQDN is required}"
SAKAI_AUTO_DDL="${SAKAI_AUTO_DDL:-true}"

SUDO='sudo'
TOMCAT_HOME='/opt/tomcat'
SAKAI_HOME="$TOMCAT_HOME/sakai"

umask 077
CONFIG_TMP="$(mktemp)"
cat > "$CONFIG_TMP" <<EOF
# Generated by deployment/configure-sakai.sh. Do not commit this file.
vendor@org.sakaiproject.db.api.SqlService=mysql
driverClassName@javax.sql.BaseDataSource=com.mysql.cj.jdbc.Driver
hibernate.dialect=org.hibernate.dialect.MySQL8Dialect
url@javax.sql.BaseDataSource=jdbc:mysql://${MYSQL_HOST}:3306/sakai?useUnicode=true&characterEncoding=UTF-8&sslMode=VERIFY_IDENTITY
username@javax.sql.BaseDataSource=sakaidb
password@javax.sql.BaseDataSource=${SAKAI_DB_PASSWORD}
validationQuery@javax.sql.BaseDataSource=
defaultTransactionIsolationString@javax.sql.BaseDataSource=TRANSACTION_READ_COMMITTED
auto.ddl=${SAKAI_AUTO_DDL}

serverName=${SAKAI_PUBLIC_FQDN}
serverUrl=https://${SAKAI_PUBLIC_FQDN}
serverId=sakai-dev
ui.service=Sakai Development Sandbox
ui.service.short=Sakai Sandbox
user.timezone=Asia/Karachi
EOF

$SUDO install -d -o tomcat -g tomcat -m 0750 "$SAKAI_HOME"
$SUDO install -o tomcat -g tomcat -m 0640 "$CONFIG_TMP" "$SAKAI_HOME/local.properties"
rm -f "$CONFIG_TMP"

$SUDO sed -i 's#-Dsakai.demo=true#-Dsakai.home=/opt/tomcat/sakai -Dsakai.demo=true#' "$TOMCAT_HOME/bin/setenv.sh"
$SUDO systemctl daemon-reload
sudo -u tomcat test -r "$SAKAI_HOME/local.properties"
sudo -u tomcat grep -q "serverUrl=https://${SAKAI_PUBLIC_FQDN}" "$SAKAI_HOME/local.properties"
